// Runtime interface of the code generated by recomp/armrecomp (docs/decisions.md D1, D6).
//
// Every recompiled guest function is `void f_<address>(GuestContext *ctx)`. It reads and writes
// the guest registers in ctx and guest memory through the RECOMP_* accessors. The embedder
// (the Vita3K fork in Phase 4, or the dynarmic test harness in recomp/tests) provides the hooks
// declared at the end.
#pragma once

#include <climits>
#include <cmath>
#include <cstdint>
#include <cstring>

namespace armrecomp {

struct GuestContext {
    uint32_t r[16]; // r15 holds the address of the last branch target written by generated code
    // flags as 0/1 values; generated code reads and writes them directly
    uint32_t n, z, c, v, q;
    uint32_t ge; // GE[3:0]
    union {
        uint64_t d[32];
        uint32_t s[64];
        float f[64];
        double fd[32];
    } vfp;
    uint32_t fpscr; // NZCV live in fpscr_nzcv until read through vmrs
    uint32_t tpidruro; // user read-only thread ID register (TLS), read by mrc p15, 0, rd, c13, c0, 3
    // exclusive monitor
    uint32_t excl_addr;
    uint32_t excl_valid;
    uint64_t excl_value;
    void *embedder; // opaque pointer for the embedder
};

// --- hooks provided by the embedder -------------------------------------------------------------

// Base of the 4 GiB guest address space (Vita3K reserves it as one block). Unused when the
// accessors below are replaced (RECOMP_CUSTOM_MEMORY), as the test harness does.
extern uint8_t *g_guest_base;

// Call the guest function at addr (bit 0 = Thumb) with the current context: a recompiled
// function when one exists, otherwise the fallback CPU (dynarmic). Returns after the callee
// returns to ctx->r[14].
void call_indirect(GuestContext *ctx, uint32_t addr);

// A call to the import stub at stub_addr (bl/blx #stub): the embedder dispatches to its HLE.
void call_import(GuestContext *ctx, uint32_t stub_addr);

// Generated code ended up somewhere it cannot continue natively: an indirect jump inside a
// function, or a return to an address other than the caller's (ctx->r[15] holds the target).
// The embedder continues on the fallback CPU from ctx->r[15]; this never returns into the
// generated function that called it.
[[noreturn]] void escape(GuestContext *ctx, uint32_t pc);

// An instruction the generator could not translate (should not happen in a full build).
[[noreturn]] void unsupported(GuestContext *ctx, uint32_t pc);

// --- memory --------------------------------------------------------------------------------------

#ifndef RECOMP_CUSTOM_MEMORY
inline uint8_t rd8(uint32_t a) { return g_guest_base[a]; }
inline uint16_t rd16(uint32_t a) {
    uint16_t v;
    std::memcpy(&v, g_guest_base + a, 2);
    return v;
}
inline uint32_t rd32(uint32_t a) {
    uint32_t v;
    std::memcpy(&v, g_guest_base + a, 4);
    return v;
}
inline uint64_t rd64(uint32_t a) {
    uint64_t v;
    std::memcpy(&v, g_guest_base + a, 8);
    return v;
}
inline void wr8(uint32_t a, uint8_t v) { g_guest_base[a] = v; }
inline void wr16(uint32_t a, uint16_t v) { std::memcpy(g_guest_base + a, &v, 2); }
inline void wr32(uint32_t a, uint32_t v) { std::memcpy(g_guest_base + a, &v, 4); }
inline void wr64(uint32_t a, uint64_t v) { std::memcpy(g_guest_base + a, &v, 8); }
#else
uint8_t rd8(uint32_t a);
uint16_t rd16(uint32_t a);
uint32_t rd32(uint32_t a);
uint64_t rd64(uint32_t a);
void wr8(uint32_t a, uint8_t v);
void wr16(uint32_t a, uint16_t v);
void wr32(uint32_t a, uint32_t v);
void wr64(uint32_t a, uint64_t v);
#endif

// --- helpers used by generated code -------------------------------------------------------------

inline uint32_t bswap32(uint32_t x) {
    return (x >> 24) | ((x >> 8) & 0xff00u) | ((x << 8) & 0xff0000u) | (x << 24);
}

// Sign-bit negation that the compiler cannot fold into a subtraction (ARM's FPNeg also flips the
// sign of a NaN, which `a + -b` -> `a - b` would lose)
inline float fneg(float x) {
    uint32_t u;
    std::memcpy(&u, &x, 4);
    u ^= 0x80000000u;
    std::memcpy(&x, &u, 4);
    return x;
}
inline double fneg(double x) {
    uint64_t u;
    std::memcpy(&u, &x, 8);
    u ^= 0x8000000000000000ull;
    std::memcpy(&x, &u, 8);
    return x;
}

// A NaN produced from non-NaN inputs is ARM's default NaN (0x7fc00000 / 0x7ff8000000000000);
// x86 produces the negative "indefinite" NaN instead. NaN inputs propagate as computed.
template <typename T, typename... In>
inline T arm_nan(T r, In... in) {
    if (r == r || ((in != in) || ...))
        return r;
    if constexpr (sizeof(T) == 4) {
        const uint32_t bits = 0x7fc00000u;
        T out;
        std::memcpy(&out, &bits, 4);
        return out;
    } else {
        const uint64_t bits = 0x7ff8000000000000ull;
        T out;
        std::memcpy(&out, &bits, 8);
        return out;
    }
}

// ARM NaN processing for two operands (FPProcessNaNs): the first signalling NaN, quieted, else the
// first quiet NaN. x86 just returns the first operand's NaN.
template <typename T>
inline bool is_snan(T x) {
    if constexpr (sizeof(T) == 4) {
        uint32_t u;
        std::memcpy(&u, &x, 4);
        return (u & 0x7f800000u) == 0x7f800000u && (u & 0x007fffffu) && !(u & 0x00400000u);
    } else {
        uint64_t u;
        std::memcpy(&u, &x, 8);
        return (u & 0x7ff0000000000000ull) == 0x7ff0000000000000ull && (u & 0x000fffffffffffffull) && !(u & 0x0008000000000000ull);
    }
}
template <typename T>
inline T quiet(T x) {
    if constexpr (sizeof(T) == 4) {
        uint32_t u;
        std::memcpy(&u, &x, 4);
        u |= 0x00400000u;
        std::memcpy(&x, &u, 4);
    } else {
        uint64_t u;
        std::memcpy(&u, &x, 8);
        u |= 0x0008000000000000ull;
        std::memcpy(&x, &u, 8);
    }
    return x;
}
template <typename T>
inline T process_nans(T r, T a, T b) {
    if (r == r)
        return r;
    if (is_snan(a)) return quiet(a);
    if (is_snan(b)) return quiet(b);
    if (a != a) return a;
    if (b != b) return b;
    return arm_nan(r);
}
template <typename T> inline T fp_add(T a, T b) { return process_nans(T(a + b), a, b); }
template <typename T> inline T fp_sub(T a, T b) { return process_nans(T(a - b), a, b); }
template <typename T> inline T fp_mul(T a, T b) { return process_nans(T(a * b), a, b); }
template <typename T> inline T fp_div(T a, T b) { return process_nans(T(a / b), a, b); }

// VFP compare result as FPSCR NZCV bits (31..28): less 1000, equal 0110, greater 0010, unordered 0011
template <typename T>
inline uint32_t vfp_compare(T a, T b) {
    if (a != a || b != b)
        return 0x30000000u;
    if (a == b)
        return 0x60000000u;
    return a < b ? 0x80000000u : 0x20000000u;
}

// vcvt to integer: round towards zero, saturate, NaN -> 0 (ARM semantics, unlike x86 cvttss2si)
template <typename T>
inline uint32_t vfp_to_s32(T x) {
    if (x != x)
        return 0;
    if (x >= T(2147483648.0))
        return 0x7fffffffu;
    if (x <= T(-2147483648.0))
        return 0x80000000u;
    return uint32_t(int32_t(x));
}
template <typename T>
inline uint32_t vfp_to_u32(T x) {
    if (x != x || x <= T(0))
        return 0;
    if (x >= T(4294967296.0))
        return 0xffffffffu;
    return uint32_t(x);
}

inline uint32_t ror32(uint32_t x, uint32_t n) {
    n &= 31;
    return n ? (x >> n) | (x << (32 - n)) : x;
}

// add with carry: result, and the carry and overflow it produces
inline uint32_t add_c(uint32_t a, uint32_t b, uint32_t carry_in, uint32_t &carry, uint32_t &overflow) {
    const uint64_t u = uint64_t(a) + uint64_t(b) + carry_in;
    const int64_t s = int64_t(int32_t(a)) + int64_t(int32_t(b)) + carry_in;
    const uint32_t r = uint32_t(u);
    carry = uint32_t(u >> 32);
    overflow = int64_t(int32_t(r)) != s;
    return r;
}

// signed saturation to `bits` (1..32) bits; sets *sat when saturated
inline int32_t ssat(int64_t v, int bits, uint32_t &sat) {
    const int64_t max = (int64_t(1) << (bits - 1)) - 1, min = -(int64_t(1) << (bits - 1));
    if (v > max) { sat = 1; return int32_t(max); }
    if (v < min) { sat = 1; return int32_t(min); }
    return int32_t(v);
}
inline uint32_t usat(int64_t v, int bits, uint32_t &sat) {
    const int64_t max = (bits == 32) ? int64_t(0xffffffff) : (int64_t(1) << bits) - 1;
    if (v > max) { sat = 1; return uint32_t(max); }
    if (v < 0) { sat = 1; return 0; }
    return uint32_t(v);
}

} // namespace armrecomp
